// TopicFor composes the full emitted CDC topic for a concept id + action
// ("created" | "updated" | "deleted").
func TopicFor(concept, action string) string { return "graph.node." + action + "." + concept }

// FilterFor composes the subscription-filter form (no `graph.` prefix).
func FilterFor(concept, action string) string { return "node." + action + "." + concept }
